content:
:root {
  --bg-gradient: radial-gradient(circle at 50% 20%, #1e293b 0%, #0f172a 100%);
  --panel-bg: rgba(30, 41, 59, 0.7);
  --panel-border: rgba(255, 255, 255, 0.08);
  --panel-blur: blur(16px);
  --shadow-main: 0 20px 50px -10px rgba(0, 0, 0, 0.5), 0 0 1px 1px rgba(255, 255, 255, 0.05);

  --btn-num-bg: rgba(255, 255, 255, 0.06);
  --btn-num-hover: rgba(255, 255, 255, 0.12);
  --btn-num-active: rgba(255, 255, 255, 0.18);
  --btn-num-text: #f8fafc;

  --btn-op-bg: rgba(59, 130, 246, 0.15);
  --btn-op-hover: rgba(59, 130, 246, 0.28);
  --btn-op-active: rgba(59, 130, 246, 0.4);
  --btn-op-text: #60a5fa;

  --btn-action-bg: rgba(244, 63, 94, 0.12);
  --btn-action-hover: rgba(244, 63, 94, 0.22);
  --btn-action-active: rgba(244, 63, 94, 0.32);
  --btn-action-text: #fb7185;

  --btn-equal-bg: linear-gradient(135deg, #3b82f6 0%, #6366f1 100%);
  --btn-equal-hover: linear-gradient(135deg, #2563eb 0%, #4f46e5 100%);
  --btn-equal-active: linear-gradient(135deg, #1d4ed8 0%, #4338ca 100%);
  --btn-equal-text: #ffffff;
  --btn-equal-shadow: 0 8px 20px -4px rgba(79, 70, 229, 0.45);

  --text-muted: #94a3b8;
  --text-dim: #64748b;
  --font-mono: 'SF Mono', Monaco, 'Fira Code', 'Courier New', monospace;
  --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-tap-highlight-color: transparent;
  user-select: none;
}

body {
  font-family: var(--font-sans);
  background: var(--bg-gradient);
  min-height: 100vh;
  min-height: 100dvh;
  padding: env(safe-area-inset-top) env(safe-area-inset-right) env(safe-area-inset-bottom) env(safe-area-inset-left);
  color: #f8fafc;
  display: flex;
  justify-content: center;
  align-items: center;
  overflow-x: hidden;
}

.calc-wrapper {
  display: flex;
  gap: 24px;
  padding: 24px;
  max-width: 860px;
  width: 100%;
  align-items: stretch;
  justify-content: center;
}

.calc-container {
  flex: 1;
  max-width: 380px;
  min-width: 320px;
  background: var(--panel-bg);
  backdrop-filter: var(--panel-blur);
  -webkit-backdrop-filter: var(--panel-blur);
  border: 1px solid var(--panel-border);
  border-radius: 28px;
  padding: 24px;
  box-shadow: var(--shadow-main);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.calc-display {
  background: rgba(15, 23, 42, 0.6);
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 18px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  align-items: flex-end;
  min-height: 104px;
  word-break: break-all;
  box-shadow: inset 0 2px 4px rgba(0, 0, 0, 0.3);
}

.calc-expression {
  font-family: var(--font-mono);
  font-size: 0.95rem;
  color: var(--text-muted);
  min-height: 22px;
  line-height: 1.4;
  text-align: right;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}

.calc-display-bottom {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  gap: 8px;
}

.calc-btn-del {
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
  color: var(--text-muted);
  border-radius: 10px;
  padding: 6px 10px;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 4px;
  font-size: 0.8rem;
  flex-shrink: 0;
  transition: all 0.15s ease;
}

.calc-btn-del:hover {
  background: rgba(255, 255, 255, 0.1);
  color: #f8fafc;
}

.calc-btn-del:active {
  transform: scale(0.96);
}

.calc-btn-del:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: 2px;
}

.calc-current-value {
  font-family: var(--font-mono);
  font-size: 2.3rem;
  font-weight: 600;
  color: #ffffff;
  letter-spacing: -0.5px;
  line-height: 1.2;
  margin-top: 4px;
  text-align: right;
  max-width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  scrollbar-width: none;
}

.calc-current-value::-webkit-scrollbar {
  display: none;
}

.calc-keypad {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 12px;
}

.calc-btn {
  font-family: var(--font-sans);
  border: none;
  outline: none;
  border-radius: 16px;
  height: 60px;
  font-size: 1.25rem;
  font-weight: 500;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.15s cubic-bezier(0.4, 0, 0.2, 1);
  position: relative;
  overflow: hidden;
}

.calc-btn:hover {
  transform: translateY(-1px);
}

.calc-btn:active {
  transform: translateY(1px) scale(0.98);
}

.calc-btn:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: 2px;
}

.calc-btn-number {
  background: var(--btn-num-bg);
  color: var(--btn-num-text);
  border: 1px solid rgba(255, 255, 255, 0.05);
}

.calc-btn-number:hover {
  background: var(--btn-num-hover);
  border-color: rgba(255, 255, 255, 0.1);
}

.calc-btn-number:active {
  background: var(--btn-num-active);
}

.calc-btn-operator {
  background: var(--btn-op-bg);
  color: var(--btn-op-text);
  font-weight: 600;
  border: 1px solid rgba(59, 130, 246, 0.2);
}

.calc-btn-operator:hover {
  background: var(--btn-op-hover);
  border-color: rgba(59, 130, 246, 0.4);
}

.calc-btn-operator:active {
  background: var(--btn-op-active);
}

.calc-btn-action {
  background: var(--btn-action-bg);
  color: var(--btn-action-text);
  font-weight: 600;
  border: 1px solid rgba(244, 63, 94, 0.2);
}

.calc-btn-action:hover {
  background: var(--btn-action-hover);
  border-color: rgba(244, 63, 94, 0.35);
}

.calc-btn-action:active {
  background: var(--btn-action-active);
}

.calc-btn-equal {
  background: var(--btn-equal-bg);
  color: var(--btn-equal-text);
  font-weight: 700;
  font-size: 1.4rem;
  box-shadow: var(--btn-equal-shadow);
  border: 1px solid rgba(255, 255, 255, 0.2);
}

.calc-btn-equal:hover {
  background: var(--btn-equal-hover);
  box-shadow: 0 10px 24px -2px rgba(79, 70, 229, 0.6);
}

.calc-btn-equal:active {
  background: var(--btn-equal-active);
  box-shadow: 0 4px 12px -2px rgba(79, 70, 229, 0.4);
}

.calc-btn-zero {
  grid-column: span 2;
  justify-content: flex-start;
  padding-left: 26px;
}

.calc-sidebar {
  width: 280px;
  background: var(--panel-bg);
  backdrop-filter: var(--panel-blur);
  -webkit-backdrop-filter: var(--panel-blur);
  border: 1px solid var(--panel-border);
  border-radius: 28px;
  padding: 24px;
  box-shadow: var(--shadow-main);
  display: flex;
  flex-direction: column;
}

.calc-sidebar-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-bottom: 16px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 12px;
}

.calc-sidebar-title {
  font-size: 1.05rem;
  font-weight: 600;
  color: #f1f5f9;
  display: flex;
  align-items: center;
  gap: 8px;
}

.calc-clear-history-btn {
  background: transparent;
  border: none;
  color: var(--text-dim);
  font-size: 0.85rem;
  cursor: pointer;
  padding: 4px 8px;
  border-radius: 6px;
  transition: all 0.2s ease;
  display: flex;
  align-items: center;
  gap: 4px;
}

.calc-clear-history-btn:hover {
  color: var(--btn-action-text);
  background: rgba(244, 63, 94, 0.1);
}

.calc-clear-history-btn:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: 2px;
}

.calc-clear-history-icon {
  display: inline;
  vertical-align: -1px;
}

.calc-history-list {
  list-style: none;
  overflow-y: auto;
  max-height: 380px;
  padding-right: 4px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.calc-history-list::-webkit-scrollbar {
  width: 4px;
}

.calc-history-list::-webkit-scrollbar-thumb {
  background: rgba(255, 255, 255, 0.12);
  border-radius: 4px;
}

.calc-history-item {
  padding: 10px 14px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.04);
  cursor: pointer;
  transition: all 0.18s ease;
  text-align: right;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.calc-history-item:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(99, 102, 241, 0.3);
  transform: translateX(-2px);
}

.calc-history-item:focus-visible {
  outline: 2px solid #60a5fa;
  outline-offset: 2px;
}

.calc-history-item-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.calc-history-timestamp {
  font-size: 0.7rem;
  color: var(--text-dim);
}

.calc-history-expression {
  font-family: var(--font-mono);
  font-size: 0.8rem;
  color: var(--text-muted);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.calc-history-result {
  font-family: var(--font-mono);
  font-size: 1.15rem;
  font-weight: 600;
  color: #38bdf8;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.calc-history-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 200px;
  color: var(--text-dim);
  font-size: 0.9rem;
  text-align: center;
  line-height: 1.6;
}

.calc-history-empty-sub {
  font-size: 0.8rem;
  margin-top: 4px;
  color: var(--text-dim);
}

@media (max-width: 720px) {
  body {
    align-items: flex-start;
    padding-top: max(16px, env(safe-area-inset-top));
    padding-bottom: max(16px, env(safe-area-inset-bottom));
    padding-left: max(0px, env(safe-area-inset-left));
    padding-right: max(0px, env(safe-area-inset-right));
  }

  .calc-wrapper {
    flex-direction: column;
    align-items: center;
    padding: 12px;
    gap: 16px;
  }

  .calc-container {
    width: 100%;
    max-width: 360px;
    padding: 18px;
    border-radius: 24px;
  }

  .calc-sidebar {
    width: 100%;
    max-width: 360px;
    padding: 18px;
    border-radius: 24px;
  }

  .calc-btn {
    height: 54px;
    font-size: 1.15rem;
  }

  .calc-current-value {
    font-size: 1.9rem;
  }
}

export type OperatorType = '+' | '-' | '×' | '÷' | null;

export type ActionType = 'clear' | 'toggleSign' | 'percent' | 'backspace' | 'equal';

export type CalcKeyType = 'number' | 'operator' | 'action' | 'equal';

export interface KeypadButton {
  label: string;
  value: string;
  type: CalcKeyType;
  action?: ActionType;
  operator?: OperatorType;
  className?: string;
}

export interface CalcHistoryItem {
  id: string;
  expression: string;
  result: string;
  timestamp: string;
  createdAt?: number;
}

import { useState, useEffect, useCallback } from 'react';
import { History, Trash2, Delete } from 'lucide-react';
import { CalcHistoryItem, OperatorType } from './types';
import './index.css';

const STORAGE_KEY = 'calculator_history';

// 初期表示用サンプル計算履歴
const INITIAL_HISTORY: CalcHistoryItem[] = [
  {
    id: 'sample-1',
    expression: '2,500 × 1.1',
    result: '2,750',
    timestamp: '10:45'
  },
  {
    id: 'sample-2',
    expression: '12,800 ÷ 4',
    result: '3,200',
    timestamp: '11:20'
  }
];

function getStoredHistory(): CalcHistoryItem[] {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    if (saved !== null) {
      const parsed = JSON.parse(saved);
      if (Array.isArray(parsed)) {
        return parsed;
      }
    }
  } catch {
    // localStorageパースエラー時は初期値を返却
  }
  return INITIAL_HISTORY;
}

function formatDisplayNumber(valueStr: string): string {
  if (valueStr === 'エラー' || valueStr === 'Infinity' || valueStr === '-Infinity') {
    return 'エラー';
  }
  const parts = valueStr.split('.');
  const intPart = parts[0];
  const decimalPart = parts[1];

  const formattedInt = intPart.replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return decimalPart !== undefined ? `${formattedInt}.${decimalPart}` : formattedInt;
}

function calculate(a: number, b: number, op: OperatorType): number {
  switch (op) {
    case '+':
      return a + b;
    case '-':
      return a - b;
    case '×':
      return a * b;
    case '÷':
      if (b === 0) return NaN;
      return a / b;
    default:
      return b;
  }
}

function roundResult(num: number): string {
  if (isNaN(num) || !isFinite(num)) return 'エラー';
  const precisionNum = parseFloat(num.toPrecision(12));
  return precisionNum.toString();
}

export default function App() {
  const [currentValue, setCurrentValue] = useState<string>('0');
  const [previousValue, setPreviousValue] = useState<string | null>(null);
  const [operator, setOperator] = useState<OperatorType>(null);
  const [waitingForOperand, setWaitingForOperand] = useState<boolean>(false);
  const [expression, setExpression] = useState<string>('');
  const [hasCalculated, setHasCalculated] = useState<boolean>(false);
  const [history, setHistory] = useState<CalcHistoryItem[]>(getStoredHistory);

  // 履歴の永続化
  useEffect(() => {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(history));
    } catch {
      // localStorage保存制限などに対する防御
    }
  }, [history]);

  // エラー状態からの復帰共通処理
  const resetErrorState = useCallback((nextValue: string) => {
    setCurrentValue(nextValue);
    setWaitingForOperand(false);
    setHasCalculated(false);
    setExpression('');
  }, []);

  // 数字入力処理
  const inputDigit = useCallback((digit: string) => {
    if (currentValue === 'エラー') {
      resetErrorState(digit);
      return;
    }

    if (waitingForOperand || hasCalculated) {
      setCurrentValue(digit);
      setWaitingForOperand(false);
      if (hasCalculated) {
        setExpression('');
        setHasCalculated(false);
      }
    } else {
      if (currentValue === '0') {
        setCurrentValue(digit);
      } else {
        if (currentValue.replace(/[^0-9]/g, '').length < 15) {
          setCurrentValue(currentValue + digit);
        }
      }
    }
  }, [currentValue, waitingForOperand, hasCalculated, resetErrorState]);

  // 小数点入力処理
  const inputDecimal = useCallback(() => {
    if (currentValue === 'エラー') {
      resetErrorState('0.');
      return;
    }

    if (waitingForOperand || hasCalculated) {
      setCurrentValue('0.');
      setWaitingForOperand(false);
      if (hasCalculated) {
        setExpression('');
        setHasCalculated(false);
      }
      return;
    }

    if (!currentValue.includes('.')) {
      setCurrentValue(currentValue + '.');
    }
  }, [currentValue, waitingForOperand, hasCalculated, resetErrorState]);

  // 全クリア（AC）
  const handleClear = useCallback(() => {
    setCurrentValue('0');
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setExpression('');
    setHasCalculated(false);
  }, []);

  // 1文字削除（バックスペース）
  const handleBackspace = useCallback(() => {
    if (currentValue === 'エラー' || waitingForOperand) {
      return;
    }
    if (hasCalculated) {
      setExpression('');
      return;
    }

    if (currentValue.length > 1) {
      if (currentValue.length === 2 && currentValue.startsWith('-')) {
        setCurrentValue('0');
      } else {
        setCurrentValue(currentValue.slice(0, -1));
      }
    } else {
      setCurrentValue('0');
    }
  }, [currentValue, waitingForOperand, hasCalculated]);

  // 符号反転（±）
  const handleToggleSign = useCallback(() => {
    if (currentValue === '0' || currentValue === 'エラー') return;

    if (currentValue.startsWith('-')) {
      setCurrentValue(currentValue.slice(1));
    } else {
      setCurrentValue('-' + currentValue);
    }
  }, [currentValue]);

  // パーセント計算（%）
  const handlePercent = useCallback(() => {
    if (currentValue === 'エラー') return;

    const val = parseFloat(currentValue);
    if (isNaN(val)) return;

    let resultNum: number;
    if (previousValue !== null && operator !== null) {
      const prev = parseFloat(previousValue);
      if (operator === '+' || operator === '-') {
        resultNum = prev * (val / 100);
      } else {
        resultNum = val / 100;
      }
    } else {
      resultNum = val / 100;
    }

    const formatted = roundResult(resultNum);
    setCurrentValue(formatted);
  }, [currentValue, previousValue, operator]);

  // 演算子選択
  const handleOperator = useCallback((nextOperator: OperatorType) => {
    if (currentValue === 'エラー') return;

    const inputValue = parseFloat(currentValue);

    if (previousValue === null) {
      setPreviousValue(currentValue);
      setExpression(`${formatDisplayNumber(currentValue)} ${nextOperator}`);
    } else if (operator && !waitingForOperand) {
      const prev = parseFloat(previousValue);
      const computed = calculate(prev, inputValue, operator);
      const rounded = roundResult(computed);

      if (rounded === 'エラー') {
        setCurrentValue('エラー');
        setPreviousValue(null);
        setOperator(null);
        setWaitingForOperand(false);
        setExpression('');
        return;
      }

      setPreviousValue(rounded);
      setCurrentValue(rounded);
      setExpression(`${formatDisplayNumber(rounded)} ${nextOperator}`);
    } else {
      setExpression(`${formatDisplayNumber(previousValue)} ${nextOperator}`);
    }

    setWaitingForOperand(true);
    setOperator(nextOperator);
    setHasCalculated(false);
  }, [currentValue, previousValue, operator, waitingForOperand]);

  // イコール計算（=）
  const handleEqual = useCallback(() => {
    if (operator === null || previousValue === null || currentValue === 'エラー') {
      return;
    }

    const prev = parseFloat(previousValue);
    const curr = parseFloat(currentValue);
    const computed = calculate(prev, curr, operator);
    const resultStr = roundResult(computed);

    const now = new Date();
    const timeStr = now.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    const fullExpr = `${formatDisplayNumber(previousValue)} ${operator} ${formatDisplayNumber(currentValue)}`;

    if (resultStr !== 'エラー') {
      const newHistoryItem: CalcHistoryItem = {
        id: Date.now().toString(),
        expression: fullExpr,
        result: formatDisplayNumber(resultStr),
        timestamp: timeStr
      };
      setHistory(prevHist => [newHistoryItem, ...prevHist].slice(0, 30));
    }

    setExpression(`${fullExpr} =`);
    setCurrentValue(resultStr);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setHasCalculated(true);
  }, [previousValue, currentValue, operator]);

  // 履歴項目の再利用
  const handleUseHistory = useCallback((item: CalcHistoryItem) => {
    const rawResult = item.result.replace(/,/g, '');
    setCurrentValue(rawResult);
    setExpression(`${item.expression} =`);
    setPreviousValue(null);
    setOperator(null);
    setWaitingForOperand(false);
    setHasCalculated(true);
  }, []);

  // 履歴全クリア
  const handleClearHistory = useCallback(() => {
    setHistory([]);
    try {
      localStorage.removeItem(STORAGE_KEY);
    } catch {
      // ignore
    }
  }, []);

  // キーボードイベントのハンドリング
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key >= '0' && e.key <= '9') {
        e.preventDefault();
        inputDigit(e.key);
      } else if (e.key === '.') {
        e.preventDefault();
        inputDecimal();
      } else if (e.key === '+' || e.key === '-') {
        e.preventDefault();
        handleOperator(e.key as OperatorType);
      } else if (e.key === '*') {
        e.preventDefault();
        handleOperator('×');
      } else if (e.key === '/') {
        e.preventDefault();
        handleOperator('÷');
      } else if (e.key === 'Enter' || e.key === '=') {
        e.preventDefault();
        handleEqual();
      } else if (e.key === 'Backspace') {
        e.preventDefault();
        handleBackspace();
      } else if (e.key === 'Escape' || e.key.toLowerCase() === 'c') {
        e.preventDefault();
        handleClear();
      } else if (e.key === '%') {
        e.preventDefault();
        handlePercent();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [inputDigit, inputDecimal, handleOperator, handleEqual, handleBackspace, handleClear, handlePercent]);

  return (
    <div className="calc-wrapper">
      {/* 電卓メインパネル */}
      <div className="calc-container">
        {/* ディスプレイ */}
        <div className="calc-display">
          <div className="calc-expression">{expression || '\u00A0'}</div>
          <div className="calc-display-bottom">
            <button
              type="button"
              className="calc-btn-del"
              onClick={handleBackspace}
              title="1文字削除 (Backspace)"
              aria-label="1文字削除"
            >
              <Delete size={14} />
              <span>DEL</span>
            </button>
            <div className="calc-current-value">
              {formatDisplayNumber(currentValue)}
            </div>
          </div>
        </div>

        {/* キーパッド */}
        <div className="calc-keypad">
          {/* 行 1 */}
          <button
            type="button"
            className="calc-btn calc-btn-action"
            onClick={handleClear}
          >
            AC
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-action"
            onClick={handleToggleSign}
          >
            ±
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-action"
            onClick={handlePercent}
          >
            %
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-operator"
            onClick={() => handleOperator('÷')}
          >
            ÷
          </button>

          {/* 行 2 */}
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('7')}
          >
            7
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('8')}
          >
            8
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('9')}
          >
            9
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-operator"
            onClick={() => handleOperator('×')}
          >
            ×
          </button>

          {/* 行 3 */}
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('4')}
          >
            4
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('5')}
          >
            5
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('6')}
          >
            6
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-operator"
            onClick={() => handleOperator('-')}
          >
            -
          </button>

          {/* 行 4 */}
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('1')}
          >
            1
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('2')}
          >
            2
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={() => inputDigit('3')}
          >
            3
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-operator"
            onClick={() => handleOperator('+')}
          >
            +
          </button>

          {/* 行 5 */}
          <button
            type="button"
            className="calc-btn calc-btn-number calc-btn-zero"
            onClick={() => inputDigit('0')}
          >
            0
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-number"
            onClick={inputDecimal}
          >
            .
          </button>
          <button
            type="button"
            className="calc-btn calc-btn-equal"
            onClick={handleEqual}
          >
            =
          </button>
        </div>
      </div>

      {/* 計算履歴サイドバー */}
      <div className="calc-sidebar">
        <div className="calc-sidebar-header">
          <div className="calc-sidebar-title">
            <History size={18} />
            <span>計算履歴</span>
          </div>
          {history.length > 0 && (
            <button
              type="button"
              className="calc-clear-history-btn"
              onClick={handleClearHistory}
              title="履歴をすべて削除"
            >
              <Trash2 size={13} className="calc-clear-history-icon" />
              <span>クリア</span>
            </button>
          )}
        </div>

        {history.length === 0 ? (
          <div className="calc-history-empty">
            <p>履歴はありません</p>
            <span className="calc-history-empty-sub">
              計算を実行するとここに表示されます
            </span>
          </div>
        ) : (
          <ul className="calc-history-list">
            {history.map((item) => (
              <li
                key={item.id}
                className="calc-history-item"
                onClick={() => handleUseHistory(item)}
                title="クリックしてこの計算結果を再利用"
              >
                <div className="calc-history-item-header">
                  <span className="calc-history-timestamp">{item.timestamp}</span>
                  <span className="calc-history-expression">{item.expression}</span>
                </div>
                <div className="calc-history-result">= {item.result}</div>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}
